"""Offline diagnostic UX only; never real provider or model qualification."""
import os,pathlib,itertools,json
from playwright.sync_api import sync_playwright,expect
out=pathlib.Path(os.environ.get('TEST_OUTPUT','work'))/'readiness';out.mkdir(parents=True,exist_ok=True)
with sync_playwright() as p:
 browser=p.chromium.launch(executable_path=os.environ['CHROMIUM_PATH'],args=['--no-sandbox']);page=browser.new_page(viewport={'width':1440,'height':1000});page.route('https://**/*',lambda r:r.abort());errors=[];posts=[];page.on('pageerror',lambda e:errors.append(str(e)));page.on('request',lambda r:posts.append(r.url) if r.method=='POST' else None)
 page.goto(os.environ['TEST_URL']);page.wait_for_function('window.THNCommand&&THNCommand.state().fresh&&THNDecision.brief()');page.locator('.nav-stack [data-view=dashboard]').click();page.add_script_tag(path=os.environ['AXE_PATH']);original=page.evaluate('JSON.stringify(THNCommand.state().candidate)');records=page.evaluate('JSON.stringify(THNLibrary.entries())');rows=[]
 page.locator('#commandRationale').evaluate('(e)=>e.open=true');page.locator('#commandSourceDetails').evaluate('(e)=>e.open=true')
 for width,lang,theme in itertools.product([1440,768,390,160],['en','ar'],['dark','light']):
  page.set_viewport_size({'width':width,'height':1000});page.locator('.terminal-topbar [data-language='+lang+']').click();page.evaluate('(t)=>document.documentElement.dataset.theme=t',theme);box=page.locator('#commandReadiness');expect(box).to_be_visible();expect(page.locator('#commandReadinessTitle')).to_contain_text('تشخيص' if lang=='ar' else 'diagnostics');expect(box).to_contain_text('EURUSD=X');expect(box).to_contain_text('neutral_consensus');expect(box).to_contain_text('risk_review_required');assert page.evaluate('document.documentElement.scrollWidth<=innerWidth+1');assert page.evaluate('JSON.stringify(THNCommand.state().candidate)')==original
  bad=page.evaluate('async()=> (await axe.run(document.querySelector("#commandReadiness"),{runOnly:{type:"tag",values:["wcag2a","wcag2aa","wcag21aa"]}})).violations.map(v=>v.id)');assert not bad,(width,lang,theme,bad)
  page.locator('#commandSourceTitle').focus();page.evaluate('document.documentElement.dataset.theme=document.documentElement.dataset.theme==="dark"?"light":"dark"');expect(page.locator('#commandSourceTitle')).to_be_focused();assert page.locator('#commandSourceDetails').evaluate('(e)=>e.open')
  if width!=160 and (lang,theme) in [('en','dark'),('ar','light')]:box.screenshot(path=str(out/f'diagnostics-{width}-{lang}.png'),animations='disabled')
  rows.append({'width':width,'language':lang,'theme':theme,'axeViolations':bad})
 page.evaluate('THNWorkspace.selectMarket("GBPUSD")');page.wait_for_function('THNContext.get().symbol==="GBPUSD"&&THNCommand.state().fresh&&THNDecision.brief()?.symbol==="GBPUSD"');expect(page.locator('#commandReadiness')).to_contain_text('GBPUSD=X');assert 'EURUSD=X' not in page.locator('#commandReadiness').inner_text()
 page.route('**/api/research/series?**',lambda r:r.fulfill(status=503,json={'ok':False,'code':'MARKET_DATA_UNAVAILABLE'}));page.evaluate('THNWorkspace.refreshMarket()');page.wait_for_function('THNResearch.series()===null');expect(page.locator('#commandReadiness')).to_contain_text('history_unavailable');assert 'GBPUSD=X' not in page.locator('#commandReadiness').inner_text();assert not any('/api/intelligence/respond' in x or '/api/order' in x for x in posts);assert page.evaluate('JSON.stringify(THNLibrary.entries())')==records;assert not errors,errors
 (out/'results.json').write_text(json.dumps({'scope':'Offline diagnostic interface only; no real feed/model qualification','profiles':rows,'contextWithdrawal':'PASS','providerOutage':'PASS','libraryUnchanged':True,'errors':errors},indent=2));browser.close();print('PASS:16 diagnostic EN/AR/theme/layout profiles, keyboard, axe, context/outage withdrawal; no model/order calls.')
